#include <stdio.h>
#include <string.h>
#include <ctype.h>

typedef struct {
    int x, y;
    int val;
} Cell;

typedef struct {
    int x, y, z;
} Vec3;

static Vec3 neg(Vec3 a) { Vec3 r = {-a.x, -a.y, -a.z}; return r; }

static int eq(Vec3 a, Vec3 b) {
    return a.x == b.x && a.y == b.y && a.z == b.z;
}

/* Rotate orientation when moving from one face to adjacent face in the net.
   n = outward normal, u = local "up", r = local "right" */
static void rotate_dir(Vec3 n, Vec3 u, Vec3 r, int dir, Vec3 *nn, Vec3 *nu, Vec3 *nr) {
    /* dir: 0=up, 1=right, 2=down, 3=left in the 2D net */
    if (dir == 0) {          /* move to cell above */
        *nn = u;
        *nu = neg(n);
        *nr = r;
    } else if (dir == 2) {   /* move to cell below */
        *nn = neg(u);
        *nu = n;
        *nr = r;
    } else if (dir == 1) {   /* move to cell right */
        *nn = r;
        *nu = u;
        *nr = neg(n);
    } else {                 /* move to cell left */
        *nn = neg(r);
        *nu = u;
        *nr = n;
    }
}

