                        for (i = 0; i < 6; i++) {
                            if (vis[i] && eq(normal[i], nn)) {
                                ok = 0;
                                break;
                            }
                        }
                        if (!ok) break;

                        vis[nx] = 1;
                        normal[nx] = nn;
                        up[nx] = nu;
                        rightv[nx] = nr;
                        q[back++] = nx;
                    } else {
                        /* orientation must be consistent */
                        if (!eq(normal[nx], nn) || !eq(up[nx], nu) || !eq(rightv[nx], nr)) {
