struct Vec3 {
    int x, y, z;
    bool operator<(const Vec3& other) const {
        if (x != other.x) return x < other.x;
        if (y != other.y) return y < other.y;
        return z < other.z;
    }
    bool operator==(const Vec3& other) const {
        return x == other.x && y == other.y && z == other.z;
    }
};

struct Ori {
    Vec3 n; // face normal
    Vec3 u; // local up on face
    Vec3 r; // local right on face
};

Vec3 neg(const Vec3& a) { return {-a.x, -a.y, -a.z}; }

Ori moveUp(const Ori& o) {
    // rotate -90 around right axis
    return {o.u, neg(o.n), o.r};
}
Ori moveDown(const Ori& o) {
    // rotate +90 around right axis
    return {neg(o.u), o.n, o.r};
}
Ori moveRight(const Ori& o) {
    // rotate +90 around up axis
    return {o.r, o.u, neg(o.n)};
}
Ori moveLeft(const Ori& o) {
    // rotate -90 around up axis
    return {neg(o.r), o.u, o.n};
}

