                    else if (k == 1) nxt = moveDown(cur);
                    else if (k == 2) nxt = moveLeft(cur);
                    else nxt = moveRight(cur);

                    pair<int,int> p = {nx,ny};
                    if (!ori.count(p)) {
                        ori[p] = nxt;
                        q.push(p);
                    } else {
                        if (!(ori[p].n == nxt.n && ori[p].u == nxt.u && ori[p].r == nxt.r)) {
                            ok = false;
                            break;
                        }
                    }
                }
            }

            // No two faces may map to same cube face.
