                if ch.strip() and ch.isdigit():
                    cells[(r,c)] = int(ch)

        if len(cells) != 6:
            results.append('false')
            continue

        # Check connectivity
        start = next(iter(cells))
        visited = {start}
        queue = deque([start])
        while queue:
            r,c = queue.popleft()
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nb = (r+dr,c+dc)
                if nb in cells and nb not in visited:
