public class Main {
    static class Face {
        int r, c, val;
        Face(int r, int c, int val) {
            this.r = r;
            this.c = c;
            this.val = val;
        }
    }

    static class Ori {
        int n, s, u, d, l, r; // numbers currently on cube directions
        Ori(int n, int s, int u, int d, int l, int r) {
            this.n = n; this.s = s; this.u = u; this.d = d; this.l = l; this.r = r;
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (!line.trim().isEmpty()) lines.add(line);
        }

        StringBuilder out = new StringBuilder();

        // Assume each test case is represented by 5 lines.
        for (int idx = 0; idx + 4 < lines.size(); idx += 5) {
            char[][] g = new char[5][5];
            for (int i = 0; i < 5; i++) {
                String s = lines.get(idx + i);
                if (s.length() < 5) {
                    StringBuilder sb = new StringBuilder(s);
                    while (sb.length() < 5) sb.append(' ');
                    s = sb.toString();
                }
                for (int j = 0; j < 5; j++) g[i][j] = s.charAt(j);
            }
            out.append(isProper(g) ? "true" : "false").append('\n');
        }

        System.out.print(out.toString());
    }

    static boolean isProper(char[][] g) {
        List<Face> faces = new ArrayList<>();
        boolean[] seenNum = new boolean[7];

        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 5; j++) {
                char ch = g[i][j];
                if (ch >= '1' && ch <= '6') {
                    int v = ch - '0';
                    if (seenNum[v]) return false; // unique numbers required
                    seenNum[v] = true;
                    faces.add(new Face(i, j, v));
                } else if (ch != '.' && ch != ' ' && ch != '0') {
                    // treat any other non-digit as empty unless it's suspicious;
                    // still okay to ignore as empty
                }
            }
        }

        if (faces.size() != 6) return false;
        for (int v = 1; v <= 6; v++) if (!seenNum[v]) return false;

        Map<Integer, Integer> posToIdx = new HashMap<>();
        for (int i = 0; i < faces.size(); i++) {
            posToIdx.put(faces.get(i).r * 5 + faces.get(i).c, i);
        }

        // Connectivity check
        boolean[] vis = new boolean[6];
        ArrayDeque<Integer> q = new ArrayDeque<>();
        vis[0] = true;
        q.add(0);
        int cnt = 1;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!q.isEmpty()) {
            int cur = q.poll();
            Face f = faces.get(cur);
            for (int k = 0; k < 4; k++) {
                int nr = f.r + dr[k], nc = f.c + dc[k];
                Integer ni = posToIdx.get(nr * 5 + nc);
                if (ni != null && !vis[ni]) {
                    vis[ni] = true;
                    q.add(ni);
                    cnt++;
                }
            }
        }
        if (cnt != 6) return false;

        // Fold simulation:
        // Assign each face to a cube orientation. If two net cells map to same cube face => overlap => invalid.
        Ori[] ori = new Ori[6];
        boolean[] assigned = new boolean[6];
        // directions indices: 0=U,1=D,2=N,3=S,4=L,5=R
        int[] cubeFaceUsedByVal = new int[7];
        Arrays.fill(cubeFaceUsedByVal, -1);

        ori[0] = new Ori(faces.get(0).val, -1, -1, -1, -1, -1); // this cell on cube front(N)
        assigned[0] = true;

        q.clear();
        q.add(0);

        while (!q.isEmpty()) {
            int cur = q.poll();
            Face f = faces.get(cur);
            Ori co = ori[cur];

            for (int k = 0; k < 4; k++) {
                int nr = f.r + dr[k], nc = f.c + dc[k];
                Integer ni = posToIdx.get(nr * 5 + nc);
                if (ni == null) continue;

                Ori no = move(co, k, faces.get(ni).val);

                if (!assigned[ni]) {
                    ori[ni] = no;
                    assigned[ni] = true;
                    q.add(ni);
                } else {
                    if (!sameOrientation(ori[ni], no)) return false;
                }
            }
        }

        // Determine which number lies on each cube direction.
        int[] dirNum = new int[6]; // U,D,N,S,L,R
        Arrays.fill(dirNum, -1);

        for (int i = 0; i < 6; i++) {
            Ori o = ori[i];
            int v = faces.get(i).val;
            int dir = getDirOfValue(o, v);
            if (dir == -1) return false;
            if (dirNum[dir] != -1 && dirNum[dir] != v) return false; // overlap on same cube face
            dirNum[dir] = v;
        }

        for (int i = 0; i < 6; i++) if (dirNum[i] == -1) return false;

        // Opposite faces on cube must sum to 7:
        // U-D, N-S, L-R
        if (dirNum[0] + dirNum[1] != 7) return false;
        if (dirNum[2] + dirNum[3] != 7) return false;
        if (dirNum[4] + dirNum[5] != 7) return false;

        return true;
    }

    static boolean sameOrientation(Ori a, Ori b) {
        return a.n == b.n && a.s == b.s && a.u == b.u && a.d == b.d && a.l == b.l && a.r == b.r;
    }

    // k: 0=up,1=down,2=left,3=right in the net
    static Ori move(Ori o, int k, int newVal) {
        int n = o.n, s = o.s, u = o.u, d = o.d, l = o.l, r = o.r;
        if (k == 0) { // neighbor above current
            return new Ori(
                    u,      // new front
                    d,      // new back
                    s,      // new up
                    n,      // new down
                    l,
                    r
            );
        } else if (k == 1) { // below
            return new Ori(
                    d,
                    u,
                    n,
                    s,
                    l,
                    r
            );
        } else if (k == 2) { // left
            return new Ori(
                    l,
                    r,
                    u,
                    d,
                    s,
                    n
            );
        } else { // right
            return new Ori(
                    r,
                    l,
                    u,
                    d,
                    n,
                    s
            );
        }
    }

    static int getDirOfValue(Ori o, int v) {
        if (o.u == v) return 0;
        if (o.d == v) return 1;
        if (o.n == v) return 2;
        if (o.s == v) return 3;
        if (o.l == v) return 4;
        if (o.r == v) return 5;
        return -1;
    }
}
